    "/vouchers": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /** @description Every voucher issued at a branch, whatever made it — a booth spin, a counter issue, the import of the old system’s codes — newest first and paged: when, its type and the prize it was won as, what it hands over (and, once used, what the till took off for it), the booth or counter, who was signed in (null: unattributed), the last four characters of its code and never the whole code, its status, and where, when, by whom and on which sale it was redeemed. Filtered by trading day (from, to — today when absent, at most 366 days), voucher type, booth, who issued it and status. Status is read from the whole row: redeemed, void, held on a till’s cart, expired once its date has passed, printed once paper exists, issued otherwise. `totals` has one line per voucher type over all filters: issued, redeemed, the redemption rate, expired, and the money the tills took off for the redeemed ones. */
        get: {
            parameters: {
                query: {
                    branchId: string;
                    from?: string;
                    to?: string;
                    definitionId?: string;
                    stationId?: string | "counter";
                    issuedBy?: string | "unattributed";
                    status?: "issued" | "printed" | "held" | "redeemed" | "expired" | "void";
                    limit?: number;
                    offset?: number;
                };
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description Default Response */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            range: {
                                from: string;
                                to: string;
                            };
                            total: number;
                            rows: {
                                /** Format: uuid */
                                id: string;
                                issuedAt: string;
                                businessDate: string;
                                type: {
                                    /** Format: uuid */
                                    id: string;
                                    code: string;
                                    nameEn: string;
                                    nameTh: string | null;
                                    kind: string;
                                };
                                prize: {
                                    /** Format: uuid */
                                    id: string;
                                    nameEn: string;
                                } | null;
                                value: {
                                    /** @enum {string} */
                                    kind: "money" | "percent" | "item" | "ticket" | "gift";
                                    text: string;
                                    redeemedSatang: number | null;
                                };
                                place: {
                                    /** @enum {string} */
                                    kind: "booth" | "counter" | "import";
                                    /** Format: uuid */
                                    stationId: string | null;
                                    name: string;
                                };
                                issuedBy: {
                                    /** Format: uuid */
                                    accountId: string;
                                    name: string | null;
                                    code: string;
                                } | null;
                                codeLast4: string;
                                source: string;
                                /** @enum {string} */
                                status: "issued" | "printed" | "held" | "redeemed" | "expired" | "void";
                                printCount: number;
                                expiresAt: string | null;
                                redeemed: {
                                    at: string;
                                    branchName: string | null;
                                    stationName: string | null;
                                    by: {
                                        /** Format: uuid */
                                        accountId: string;
                                        name: string | null;
                                        code: string;
                                    } | null;
                                    /** Format: uuid */
                                    saleId: string | null;
                                    receiptNumber: string | null;
                                } | null;
                            }[];
                            totals: {
                                type: {
                                    /** Format: uuid */
                                    id: string;
                                    code: string;
                                    nameEn: string;
                                    kind: string;
                                };
                                /** @enum {string} */
                                valueKind: "money" | "percent" | "item" | "ticket" | "gift";
                                issued: number;
                                redeemed: number;
                                redemptionRate: number | null;
                                expired: number;
                                handedOverSatang: number;
                            }[];
                        };
                    };
                };
            };
        };
        put?: never;
        post?: never;
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
